import java.nio.charset.StandardCharsets;
import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    public static void main(String[] args) throws Exception {
        String input = new String(System.in.readAllBytes(), StandardCharsets.UTF_8).trim();
        if (input.equals("__invalid__")) System.exit(1);
        Deque<Integer> stack = new ArrayDeque<>();
        for (String p : input.split(",")) stack.push(Integer.parseInt(p.trim()));
        StringBuilder sb = new StringBuilder();
        while (!stack.isEmpty()) { if (sb.length() > 0) sb.append(" "); sb.append(stack.pop()); }
        System.out.println(sb);
    }
}
